238	
239	    /**
240	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
241	     * the canonical form each stored value must take: the address is trimmed,
242	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
243	     * telephone is converted to E.164, any email is lower-cased and a missing
244	     * registration date defaults to today. Field-level rejections are reported here
245	     * rather than inline in {@link #addOwner}, and normalisation runs before any
246	     * household comparison so those comparisons see the canonical values.
247	     *
248	     * @param owner the freshly-mapped owner to normalise
249	     * @return {@code true} if the fields are valid, or {@code false} if the address
250	     *         is blank after normalisation, the telephone cannot form a valid
251	     *         E.164 number, or a supplied registration date is later than the
252	     *         server date, in which case the request must be rejected with
253	     *         {@code 400 Bad Request}
254	     */
255	    private boolean normalizeNewOwner(Owner owner) {
256	        String address = Owner.normalizeAddress(owner.getAddress());
257	        if (address.isEmpty()) {
258	            return false;
259	        }
260	        owner.setAddress(address);
261	        String telephone = toE164(owner.getTelephone());
262	        if (telephone == null) {
263	            return false;
264	        }
265	        owner.setTelephone(telephone);
266	        if (owner.getEmail() != null) {
267	            owner.setEmail(owner.getEmail().toLowerCase());
268	        }
269	        if (!postcodeValidForCity(owner)) {
270	            return false;
271	        }
272	        if (owner.getRegistrationDate() == null) {
273	            owner.setRegistrationDate(LocalDate.now());
274	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
275	            return false;
276	        }
277	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
278	        return true;
279	    }
280	
281	    /** Region -> inclusive 4-digit postcode range {low, high}. */
282	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
283	        "NSW", new int[] {2000, 2099},
284	        "VIC", new int[] {3000, 3099},
285	        "QLD", new int[] {4000, 4099});
286	
287	    /**
288	     * Validate the owner's postcode when one is supplied. A postcode is optional: an
289	     * owner created without one is accepted. When present it must be exactly four
290	     * digits and, when the owner's city maps to a known region (see
291	     * {@link Owner#getLocality()}), fall within that region's inclusive postcode
292	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
293	     * region accepts any four-digit postcode.
294	     *
295	     * @param owner the freshly-mapped owner being created
296	     * @return {@code true} if the postcode is absent or valid, {@code false} if it is
297	     *         malformed or out of range for the city's region (reject with 400)
298	     */
299	    private static boolean postcodeValidForCity(Owner owner) {
300	        String postcode = owner.getPostcode();
301	        if (postcode == null) {
302	            return true;
303	        }
304	        if (!postcode.matches("\\d{4}")) {
305	            return false;
306	        }
307	        int[] range = REGION_POSTCODES.get(owner.getLocality());
308	        if (range == null) {
309	            return true;
310	        }
311	        int value = Integer.parseInt(postcode);
312	        return value >= range[0] && value <= range[1];
313	    }
314	
315	    /**
316	     * Roll the given date forward to the next business day when it falls on a
317	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
318	     * weekday is returned unchanged. Applied to the effective registration date
319	     * (whether supplied in the request or defaulted to the server date) so that
320	     * every value derived from it uses the adjusted business day.
321	     *
322	     * @param date the effective registration date
323	     * @return the same date if it is a weekday, otherwise the next Monday
324	     */
325	    private static LocalDate rollToBusinessDay(LocalDate date) {
326	        switch (date.getDayOfWeek()) {
327	            case SATURDAY:
328	                return date.plusDays(2);
329	            case SUNDAY:
330	                return date.plusDays(1);
331	            default:
332	                return date;
333	        }
334	    }
335	
336	    /**
337	     * Determine whether the candidate owner's identity key collides with any existing
338	     * owner's. This is the single, consolidated duplicate check: it subsumes the
339	     * former separate telephone, email and household checks by comparing the whole
340	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
341	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
342	     * that agree on some — but not all — of the key's parts (for example two members of
343	     * the same household with different telephones) are not duplicates. Evaluated after
344	     * normalisation and household resolution, so the candidate's key reflects its
345	     * canonical field values and any household it has joined.
346	     *
347	     * @param owner the candidate owner being created, after household resolution
348	     * @return {@code true} if an existing owner has the same identity key
349	     */
350	    private boolean identityKeyAlreadyUsed(Owner owner) {
351	        String identityKey = owner.getIdentityKey();
352	        return this.clinicService.findAllOwners().stream()
353	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
354	    }
355	
356	    /**
357	     * Find an existing owner that belongs to the same household as the given owner,
358	     * i.e. shares the same last name and address (compared case-insensitively with
359	     * runs of whitespace collapsed to a single space).
360	     *
361	     * @param owner the candidate owner being created
362	     * @return the matching existing owner, or empty if none exists
363	     */
364	    private Optional<Owner> findHouseholdMember(Owner owner) {
365	        return this.clinicService.findAllOwners().stream()
366	            .filter(existing -> existing.sameHouseholdAs(owner))
367	            .findFirst();
368	    }
369	
370	    /**
371	     * Assign the joining owner and an existing household member the same stable
372	     * household identifier. The identifier is derived deterministically from the
373	     * shared household key (last name + address, normalised), so every owner in a
374	     * household resolves to the same value; the existing member is updated when it
375	     * does not already carry it.
376	     *
377	     * @param owner    the owner being created
378	     * @param existing an existing owner in the same household
379	     */
380	    private void joinHousehold(Owner owner, Owner existing) {
381	        String householdId = UUID
382	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
383	        owner.setHouseholdId(householdId);
384	        if (!householdId.equals(existing.getHouseholdId())) {
385	            existing.setHouseholdId(householdId);
386	            this.clinicService.saveOwner(existing);
387	        }
388	    }
389	
390	    /**
391	     * Count how many owners belong to the given owner's household once this create
392	     * completes: the owners that already share its {@code householdId} plus the owner
393	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
394	     * so the household identifier (and any existing member updated to it) is already in
395	     * place. An owner that has not joined a household (no {@code householdId}) is a
396	     * household of one.
397	     *
398	     * @param owner the candidate owner being created, after household resolution
399	     * @return the household member count after this create (at least {@code 1})
400	     */
401	    private int householdSize(Owner owner) {
402	        String householdId = owner.getHouseholdId();
403	        if (householdId == null) {
404	            return 1;
405	        }
406	        long existing = this.clinicService.findAllOwners().stream()
407	            .filter(other -> householdId.equals(other.getHouseholdId()))
408	            .count();
409	        return (int) existing + 1;
410	    }
411	
412	    /**
413	     * Count the existing owners that share the given owner's first and last name,
414	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
415	     * before the new owner is saved, so the result reflects only owners that
416	     * already existed at creation time.
417	     *
418	     * @param owner the candidate owner being created
419	     * @return the number of existing namesakes
420	     */
421	    private int countNamesakes(Owner owner) {
422	        String firstName = normalizeName(owner.getFirstName());
423	        String lastName = normalizeName(owner.getLastName());
424	        return (int) this.clinicService.findAllOwners().stream()
425	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
426	                && normalizeName(existing.getLastName()).equals(lastName))
427	            .count();
428	    }
429	
430	    private static String normalizeName(String value) {
431	        return value == null ? "" : value.trim().toLowerCase();
432	    }
433	
434	    /**
435	     * Determine whether the given city has already reached its owner capacity, i.e.
436	     * it already contains 50 or more existing owners (compared case-insensitively
437	     * with surrounding whitespace trimmed). A new owner may not be created in a city
438	     * that is at capacity.
439	     *
440	     * @param city the candidate owner's city
441	     * @return {@code true} if the city already holds 50 or more owners
442	     */
443	    private boolean cityIsAtCapacity(String city) {
444	        String normalizedCity = normalizeName(city);
445	        long count = this.clinicService.findAllOwners().stream()
446	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
447	            .count();
448	        return count >= 50;
449	    }
450	
451	    /**
452	     * Determine whether the daily owner-creation limit has already been reached, i.e.
453	     * 100 or more owners already carry the given registration date. A new owner may
454	     * not be created once that day's cap is reached.
455	     *
456	     * @param registrationDate the registration date the new owner would be created with
457	     * @return {@code true} if 100 or more existing owners share that registration date
458	     */
459	    private boolean dailyLimitReached(LocalDate registrationDate) {
460	        long count = this.clinicService.findAllOwners().stream()
461	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
462	            .count();
463	        return count >= 100;
464	    }
465	
466	    /**
467	     * Determine whether more than 80 owners have already been created for the given
468	     * registration date, i.e. strictly more than 80 existing owners carry that date.
469	     * Evaluated before the new owner is saved, so it reflects only owners that
470	     * already existed at creation time.
471	     *
472	     * @param registrationDate the registration date the new owner would be created with
473	     * @return {@code true} if more than 80 existing owners share that registration date
474	     */
475	    private boolean bulkSignupWarning(LocalDate registrationDate) {
476	        long count = this.clinicService.findAllOwners().stream()
477	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
478	            .count();
479	        return count > 80;
480	    }
481	
482	    /**
483	     * Build the customer code assigned to the given owner, formatted
484	     * {@code <REGION>-<HASH8>}: REGION is the canonical region derived for the owner
485	     * (see {@link Owner#regionForOwner()}, the postcode-then-city region also exposed
486	     * as its {@link Owner#getLocality() locality}) and HASH8 is the first eight
487	     * upper-case hexadecimal characters of the SHA-256 digest of the owner's
488	     * normalised telephone concatenated with its last name (e.g.
489	     * {@code NSW-9F86D081}). The whole owner is passed so the code can be derived from
490	     * whichever of its (already normalised) fields the identity scheme requires.
491	     *
492	     * @param owner the owner being created, with its fields already normalised
493	     * @return the assigned customer code
494	     */
495	    private String customerCode(Owner owner) {
496	        String region = owner.regionForOwner();
497	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
498	        return String.format("%s-%s", region, hash8);
499	    }
500	
501	    /**
502	     * The first eight upper-case hexadecimal characters of the SHA-256 digest of the
503	     * UTF-8 bytes of the given value.
504	     */
505	    private static String sha256Hex8(String value) {
506	        try {
507	            byte[] digest = MessageDigest.getInstance("SHA-256")
508	                .digest(value.getBytes(StandardCharsets.UTF_8));
509	            StringBuilder hex = new StringBuilder();
510	            for (byte b : digest) {
511	                hex.append(String.format("%02X", b));
512	                if (hex.length() >= 8) {
513	                    break;
514	                }
515	            }
516	            return hex.substring(0, 8);
517	        } catch (NoSuchAlgorithmException e) {
518	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
519	        }
520	    }
521	
522	    /**
523	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
524	     * one place so it stays in step with the owner's identity: it reports the assigned
525	     * customer code alongside the owner's id, registration date and membership level.
526	     *
527	     * @param owner the owner that has just been created and saved
528	     */
529	    private void auditOwnerCreated(Owner owner) {
530	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
531	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
532	    }
533	
534	    /**
535	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
536	     * where {@code <customerCode>} is the owner's already-assigned customer code and
537	     * YY is the last two digits of the registration date's year (e.g.
538	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
539	     * have been set.
540	     *
541	     * @param owner the owner being created, with customer code and registration date
542	     *              already assigned
543	     * @return the assigned membership number
544	     */
545	    private String membershipNumber(Owner owner) {
546	        int yy = owner.getRegistrationDate().getYear() % 100;
547	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
548	    }
549	
550	    /**
551	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
552	     * code when present, otherwise assume country code '+61' and drop a single
553	     * leading '0' from the national digits. Spaces, dashes and brackets are
554	     * stripped. The result must contain 8 to 15 digits after the '+'.
555	     *
556	     * <p>In addition, the national-number length is validated against the country
557	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
558	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
559	     * whose national-number length is wrong for its country code is rejected.
560	     *
561	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
562	     *         input cannot form a valid E.164 number.
563	     */
564	    private static String toE164(String raw) {
565	        if (raw == null) {
566	            return null;
567	        }
568	        String cleaned = raw.replaceAll("[\\s()-]", "");
569	        String digits;
570	        if (cleaned.startsWith("+")) {
571	            digits = cleaned.substring(1);
572	        } else {
573	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
574	            digits = "61" + national;
575	        }
576	        if (!digits.matches("\\d{8,15}")) {
577	            return null;
578	        }
579	        if (!nationalNumberLengthValid(digits)) {
580	            return null;
581	        }
582	        return "+" + digits;
583	    }
584	
585	    /**
586	     * Validate the length of the national number (the digits after the country
587	     * code) against the country code carried by the given E.164 digit string: a
588	     * {@code 61} (Australia) number requires exactly 9 national digits and a
589	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
590	     * without a pinned length are accepted (only the generic 8-15 digit rule
591	     * applies to them).
592	     *
593	     * @param digits the E.164 digits without the leading '+'
594	     * @return {@code true} if the national-number length is correct for the country
595	     */
596	    private static boolean nationalNumberLengthValid(String digits) {
597	        if (digits.startsWith("61")) {
598	            return digits.length() - 2 == 9;
599	        }
600	        if (digits.startsWith("1")) {
601	            return digits.length() - 1 == 10;
602	        }
603	        return true;
604	    }
605	}
